(async () => {
const $ = (q) => document.querySelector(q);
const esc = (s='') => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const config=window.CENTER_CONFIG||{};
const ready=Boolean(config.supabaseUrl&&config.supabaseKey);
const plan=window.CENTER_PLAN;
const activities=['인강 수강','문제 풀이','채점하기','오답 다시 풀기'];
let session,me,records=[],students=[],links=[],selected=1,view='study',busy=false,dirty=false,adminTarget=null;
try{session=JSON.parse(sessionStorage.getItem('center-session')||'null')}catch{}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function remember(s){session=s;if(s)sessionStorage.setItem('center-session',JSON.stringify(s));else sessionStorage.removeItem('center-session')}
async function request(path,{method='GET',body,auth=true,prefer}={}){
 if(!ready)throw Error('온라인 저장 연결이 필요합니다. 운영 안내를 확인해 주세요.');
 if(auth&&session?.expires_at<Date.now()/1000+60){
  const rr=await fetch(config.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:config.supabaseKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});
  if(!rr.ok){remember(null);throw Error('로그인이 만료되었습니다. 다시 로그인해 주세요.')}const s=await rr.json();remember({...s,expires_at:Date.now()/1000+s.expires_in});
 }
 const r=await fetch(config.supabaseUrl+path,{method,headers:{apikey:config.supabaseKey,'Content-Type':'application/json',...(auth&&session?{Authorization:`Bearer ${session.access_token}`} :{}),...(prefer?{Prefer:prefer}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});
 if(!r.ok){let e;try{e=await r.json()}catch{}throw Error(r.status===401?'아이디 또는 비밀번호를 확인해 주세요.':r.status===403?'이 작업에 대한 권한이 없습니다.':e?.message||e?.error_description||e?.error||'서버 연결을 확인하고 다시 시도해 주세요.');}return r.status===204?null:r.text().then(t=>t?JSON.parse(t):null);
}
function record(day,user=adminTarget||me?.id){return records.find(r=>r.day===day&&r.student_id===user)||{day,student_id:user,checks:[false,false,false,false],correct:null,total:null,minutes:null,note:'',study_date:''}}
function metric(id){const rs=records.filter(r=>r.student_id===id);return{done:rs.filter(r=>r.checks.every(Boolean)).length,checks:rs.reduce((a,r)=>a+r.checks.filter(Boolean).length,0),lectures:rs.filter(r=>r.checks[0]&&r.day%8!==0).length*2,minutes:rs.reduce((a,r)=>a+(r.minutes||0),0)}}
const brand=()=>`<div class="brand"><img class="logo" src="./assets/center-logo.png" alt="STEAMedu 센터 로고"><small>레고에듀케이션 청라스마트러닝센터</small></div>`;
function login(role=null){
 me=null;
 const admin=role==='admin';
 $('#app').innerHTML=`<main class="login"><section class="login-left">${brand()}<div><span class="eyebrow">MY MATH JOURNEY</span><h1>하루 두 강의,<br><em>수학이 쌓이는 40일.</em></h1><p class="muted">강의를 듣고, 스스로 풀고, 다시 확인해요.</p><div class="steps"><span>70개 강의</span><span>5번의 복습</span><span>나만의 학습 기록</span></div></div><small>레고에듀케이션 청라스마트러닝센터</small></section><section class="login-right"><div class="login-card"><span class="tag">40일 수학 학습실</span>${!role?'<h2 style="margin-top:24px">학습실에 오신 것을 환영합니다</h2><p class="muted">이용할 페이지를 선택해 주세요.</p><div class="entry-options"><button id="student-entry"><strong>학생 페이지 →</strong><span>오늘의 학습과 나의 진도 확인</span></button><button class="secondary" id="admin-entry"><strong>관리자 페이지 →</strong><span>학생 계정 발급과 학습 관리</span></button></div>':`<h2 style="margin-top:24px">${admin?'관리자 로그인':'학생 로그인'}</h2><p class="muted">${admin?'관리자 계정으로 학생들의 학습을 관리하세요.':'센터에서 발급받은 계정으로 로그인하세요.'}</p><form id="login"><label>아이디<input name="username" autocomplete="username" value="${admin?'admin':''}" placeholder="${admin?'관리자 아이디':'학생 아이디'}" required maxlength="80"></label><label>비밀번호<input name="password" type="password" autocomplete="current-password" placeholder="비밀번호를 입력하세요" required></label><p class="error" id="login-error" role="alert"></p><button type="submit">${admin?'관리자 페이지 로그인':'학생 페이지 로그인'} →</button></form><button class="quiet" id="back-home">← 메인 화면</button>`}${!ready?'<p class="note" style="margin-top:24px">로그인 서비스 연결 준비 중입니다. 센터에서 최초 설정을 마친 뒤 이용할 수 있습니다.</p>':''}</div></section></main>`;
 if(!role){$('#student-entry').onclick=()=>login('student');$('#admin-entry').onclick=()=>login('admin');return;}
 $('#back-home').onclick=()=>login();
 $('#login').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const f=new FormData(e.target);const username=f.get('username').trim().toLowerCase();const result=await request('/auth/v1/token?grant_type=password',{method:'POST',auth:false,body:{email:username.includes('@')?username:username+'@students.center.invalid',password:f.get('password')}});remember({...result,expires_at:Date.now()/1000+result.expires_in});await load();if(me.role!==role){remember(null);me=null;records=[];students=[];throw Error(admin?'관리자 계정으로 로그인해 주세요.':'학생 계정으로 로그인해 주세요.');}view=admin?'admin':'study';render()}catch(x){$('#login-error').textContent=x.message}finally{b.disabled=false}};
}
async function load(){const profiles=await request('/rest/v1/profiles?select=*');me=profiles.find(p=>p.id===session.user.id);if(!me)throw Error('등록된 학생 정보가 없습니다. 센터에 문의해 주세요.');students=profiles.filter(p=>p.role==='student');[records,links]=await Promise.all([request('/rest/v1/progress?select=*'),request('/rest/v1/lecture_links?select=*')]);selected=plan.find(p=>!record(p.day,me.id).checks.every(Boolean))?.day||40;}
function render(){dirty=false;const admin=me.role==='admin';$('#app').innerHTML=`<div class="layout"><aside class="sidebar">${brand()}<nav class="nav" aria-label="주 메뉴">${admin?`<button data-view="admin" class="${view==='admin'?'active':''}">▦ 학생 진도 관리</button><button data-view="links" class="${view==='links'?'active':''}">▷ 강의 링크 관리</button>`:`<button data-view="study" class="${view==='study'?'active':''}">▦ 나의 학습실</button>`}<button data-view="account" class="${view==='account'?'active':''}">○ 내 계정</button><button id="logout">↪ 로그아웃</button></nav><div class="side-bottom"><strong>하루의 공부를 한눈에</strong><br>인강 → 문제 → 채점 → 오답<br><br>청라스마트러닝센터<br><span class="muted">40일 수학 학습 프로그램</span></div></aside><main class="workspace"><header class="topbar"><span>40일 수학 <span class="muted"> / ${admin?'관리자 학습 관리':'나의 학습실'}</span></span><span><span class="avatar">${esc(me.name.slice(0,1))}</span>${esc(me.name)} ${admin?'선생님':'학생'}</span></header><div id="content"></div><footer>© 청라스마트러닝센터 · 센터 로고의 저작권은 센터에 있습니다.</footer></main></div>`;
 $('#content').innerHTML=view==='admin'?adminView():view==='links'?linksView():view==='account'?accountView():studyView();
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(()=>{view=b.dataset.view;adminTarget=null;render()}));
 $('#logout').onclick=()=>navigate(async()=>{try{await request('/auth/v1/logout',{method:'POST'})}catch{}remember(null);records=[];students=[];login()});
 bind();
}
function navigate(fn){if(busy)return;if(dirty&&!confirm('저장하지 않은 내용이 있습니다. 이동하시겠어요?'))return;fn()}
function studyView(){const person=adminTarget?students.find(s=>s.id===adminTarget):me;const m=metric(person.id),r=record(selected),p=plan[selected-1];const percent=Math.round(m.checks/160*1000)/10;return `<div class="heading"><div><h1>${adminTarget?esc(person.name)+' 학생의 학습 기록':'오늘도 한 걸음, 수학 공부'}</h1><p>${adminTarget?'학생이 저장한 기록을 확인해 주세요.':'오늘의 학습을 마치고 네 가지 활동을 체크해 주세요.'}</p></div><span class="tag">40일 완주 챌린지</span></div><section class="stats"><div class="card stat primary"><small>전체 학습 진도</small><strong>${percent}%</strong><small>완료 활동 ${m.checks} / 160개</small><progress value="${m.checks}" max="160" aria-label="전체 학습 진도"></progress></div><div class="card stat"><small>완료한 학습일</small><strong>${m.done} <small>/ 40일</small></strong><small>네 가지 활동을 모두 완료한 날</small></div><div class="card stat"><small>수강 완료 강의</small><strong>${m.lectures} <small>/ 70강</small></strong><small>누적 공부 시간 ${m.minutes}분</small></div></section><div class="content-grid"><div class="stack" style="grid-template-columns:1fr"><section class="card"><div class="section-top"><h2>40일 학습 여정</h2><small>학습일을 선택하세요</small></div><div class="day-grid">${plan.map(d=>`<button class="day-btn ${d.review?'review':''} ${record(d.day).checks.every(Boolean)?'complete':''} ${selected===d.day?'current':''}" data-day="${d.day}" aria-pressed="${selected===d.day}">${d.day}<small>${d.review?'복습':record(d.day).checks.every(Boolean)?'완료':'일차'}</small></button>`).join('')}</div><div class="legend"><span>초록 · 완료</span><span>노랑 · 복습일</span><span>테두리 · 선택한 날</span></div></section><section class="card"><div class="section-top"><h2>${selected}일차 · ${p.review?'복습과 점검':'오늘의 학습'}</h2><span class="tag">${p.review?'복습하는 날':`인강 ${p.minutes}분`}</span></div>${p.review?`<p>${selected===40?'전체 범위 최종 복습':`${(selected/8-1)*14+1}~${selected/8*14}강 복습`}</p><p class="muted">어려웠던 강의 부분을 다시 보고 ${selected===40?'15~20':'10~15'}문항을 골라 풀어보세요. 강의 다시 보기는 해당 학습일에서 열 수 있어요.</p>`:p.lessons.map(l=>{const url=links.find(x=>x.lecture===l.number)?.url;return `<div class="lesson"><span class="lesson-num">${String(l.number).padStart(2,'0')}</span><div class="lesson-copy"><h3>${esc(l.title)}</h3><small>교재 ${esc(l.pages)}쪽</small></div>${url&&validUrl(url)?`<a class="button secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">강의 보기 ↗</a>`:'<small>강의 링크 등록 대기</small>'}</div>`}).join('')}${selected===1?'<p class="note">오늘은 오리엔테이션 6분이 포함되어 있어요. 강의 사이에는 5~10분 쉬어 주세요.</p>':''}${selected===37?'<p class="note">66강은 원본 제목과 상세 설명이 다릅니다. 수강할 때 실제 내용을 확인해 주세요.</p>':''}<form id="daily"><div class="check-list">${activities.map((a,i)=>`<label class="check-item"><input type="checkbox" name="check${i}" ${r.checks[i]?'checked':''} ${adminTarget?'disabled':''}>${a}${p.review&&i===0?' (취약 강의 복습)':''}</label>`).join('')}</div><div class="form-grid"><label>맞힌 문항 수<input type="number" min="0" max="1000" name="correct" value="${r.correct??''}" ${adminTarget?'disabled':''}></label><label>전체 문항 수<input type="number" min="0" max="1000" name="total" value="${r.total??''}" ${adminTarget?'disabled':''}></label><label>공부한 시간 (분)<input type="number" min="0" max="1440" name="minutes" value="${r.minutes??''}" ${adminTarget?'disabled':''}></label><label>실제 학습 날짜<input type="date" name="study_date" value="${esc(r.study_date||'')}" ${adminTarget?'disabled':''}></label><label class="full">핵심 개념 · 오답 · 다음 목표<textarea name="note" maxlength="3000" placeholder="어려웠던 개념, 다시 볼 강의나 틀린 문항을 적어 보세요." ${adminTarget?'disabled':''}>${esc(r.note)}</textarea></label></div><p class="error" id="save-error" role="alert"></p><div class="save-row"><small>${adminTarget?'학생 본인만 기록을 수정할 수 있습니다.':'체크 후 저장 버튼을 눌러 주세요.'}</small>${!adminTarget?'<button type="submit">학습 기록 저장 ✓</button>':''}</div></form></section></div><aside class="stack"><section class="card"><h2>나의 학습 구간</h2>${[0,1,2,3,4].map(i=>{let done=0;for(let d=i*8+1;d<=(i+1)*8;d++)if(record(d).checks.every(Boolean))done++;return `<div class="period"><div class="section-top" style="margin-bottom:5px"><p>${i*8+1}–${(i+1)*8}일차</p><small>${done} / 8일</small></div><small>${i*14+1}–${(i+1)*14}강 ${i===4?'· 최종 복습':'· 구간 복습'}</small><progress value="${done}" max="8" aria-label="${i+1}구간 완료율"></progress></div>`}).join('')}</section><section class="card"><h2>이렇게 공부해요</h2><p class="muted" style="font-size:.875rem">인강 56~58분<br>문제 풀이 25~35분<br>채점 5~10분<br>오답 정리 15~20분</p><div class="note">오답이 없다면 채점 결과를 확인한 뒤 오답 항목을 체크하세요.</div></section></aside></div>`}
function adminView(){return `<div class="heading"><div><h1>학생 진도 관리</h1><p>학생별 학습 현황을 확인하고 학습을 도와주세요.</p></div><button class="secondary" id="refresh">새로고침</button></div><section class="stats"><div class="card stat primary"><small>등록 학생</small><strong>${students.length}명</strong><small>센터에서 관리하는 학습 계정</small></div><div class="card stat"><small>평균 학습 진도</small><strong>${students.length?Math.round(students.reduce((a,s)=>a+metric(s.id).checks,0)/(students.length*160)*1000)/10:0}%</strong></div><div class="card stat"><small>40일 완주 학생</small><strong>${students.filter(s=>metric(s.id).done===40).length}명</strong></div></section><section class="card"><h2>학생별 학습 현황</h2><div class="table-wrap"><table><thead><tr><th>학생</th><th>학년</th><th>시작일</th><th>진도율</th><th>완료 일수</th><th>학습 기록</th></tr></thead><tbody>${students.map(s=>{const m=metric(s.id);return `<tr><td>${esc(s.name)}</td><td>${esc(s.grade)}</td><td>${esc(s.start_date||'미지정')}</td><td>${Math.round(m.checks/160*1000)/10}%<progress value="${m.checks}" max="160" aria-label="${esc(s.name)} 진도율"></progress></td><td>${m.done} / 40일</td><td><button class="secondary" data-student="${esc(s.id)}">상세 보기</button></td></tr>`}).join('')||'<tr><td colspan="6">아직 등록된 학생이 없습니다. 아래에서 학생 계정을 발급해 주세요.</td></tr>'}</tbody></table></div></section><div class="admin-tools"><section class="card"><h2>학생 계정 발급</h2><form id="create-student" class="form-grid"><label>이름<input name="name" required maxlength="40"></label><label>학년<input name="grade" required maxlength="30" placeholder="예: 중학교 1학년"></label><label>아이디<input name="username" required pattern="[a-z0-9_-]{3,30}" placeholder="영문 소문자·숫자 3~30자"></label><label>임시 비밀번호<input name="password" type="password" required minlength="10" autocomplete="new-password"></label><label class="full">학습 시작일<input type="date" name="start_date" required></label><p class="error full" id="student-error" role="alert"></p><button type="submit" class="full">학생 계정 만들기</button></form></section><section class="card"><h2>학생 비밀번호 재설정</h2><form id="reset-student" class="form-grid"><label class="full">학생<select name="id" required><option value="">학생 선택</option>${students.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.grade)}</option>`).join('')}</select></label><label class="full">새 임시 비밀번호<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><p class="error full" id="reset-error" role="alert"></p><button class="secondary full" type="submit">비밀번호 재설정</button></form><p class="muted" style="margin-top:20px;font-size:.875rem">학생에게 아이디와 임시 비밀번호를 개별 안내해 주세요. 학생은 내 계정에서 비밀번호를 변경할 수 있습니다.</p></section></div>`}
function validUrl(s){try{return new URL(s).protocol==='https:'}catch{return false}}
function linksView(){return `<div class="heading"><div><h1>강의 링크 관리</h1><p>강의별 HTTPS 주소를 등록하면 학생 화면에 ‘강의 보기’가 표시됩니다.</p></div></div><section class="card"><form id="links">${plan.flatMap(p=>p.lessons).map(l=>`<div class="link-row"><span class="lesson-num">${l.number}</span><label>${esc(l.title)}<input type="url" name="lecture${l.number}" value="${esc(links.find(x=>x.lecture===l.number)?.url||'')}" placeholder="https:// 강의 주소"></label></div>`).join('')}<p class="error" id="link-error" role="alert"></p><button type="submit">강의 링크 저장</button></form></section>`}
function accountView(){return `<div class="heading"><div><h1>내 계정</h1><p>${esc(me.name)} · ${esc(me.grade||'관리자')}</p></div></div><section class="card"><h2>비밀번호 변경</h2><form id="password" class="pass-form"><label>새 비밀번호<input name="password" type="password" required minlength="10" autocomplete="new-password"></label><label>새 비밀번호 확인<input name="confirm" type="password" required minlength="10" autocomplete="new-password"></label><button type="submit">변경하기</button></form><p id="password-error" class="error" role="alert"></p></section>`}
function bind(){document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>navigate(()=>{selected=+b.dataset.day;render()}));document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{adminTarget=b.dataset.student;selected=1;view='study';render()});
 if($('#daily')){$('#daily').oninput=()=>dirty=true;$('#daily').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target);const number=k=>f.get(k)===''?null:Number(f.get(k));const correct=number('correct'),total=number('total');if((correct!==null&&total===null)||(correct===null&&total!==null)||(correct??0)>(total??0)){$('#save-error').textContent='맞힌 문항 수와 전체 문항 수를 함께 입력하고, 맞힌 문항 수가 전체를 넘지 않는지 확인해 주세요.';return}const row={student_id:me.id,day:selected,checks:activities.map((_,i)=>f.has('check'+i)),correct,total,minutes:number('minutes'),study_date:f.get('study_date')||null,note:f.get('note'),updated_at:new Date().toISOString()};busy=true;e.submitter.disabled=true;try{await request('/rest/v1/progress?on_conflict=student_id,day',{method:'POST',body:row,prefer:'resolution=merge-duplicates'});records=records.filter(r=>!(r.student_id===row.student_id&&r.day===row.day));records.push(row);render();toast('학습 기록을 저장했습니다.')}catch(x){$('#save-error').textContent=x.message}finally{busy=false;if(e.submitter)e.submitter.disabled=false}}}
 if($('#refresh'))$('#refresh').onclick=async e=>{e.target.disabled=true;try{await load();render();toast('최신 기록을 불러왔습니다.')}catch(x){toast(x.message)}finally{e.target.disabled=false}};
 for(const [id,action,out] of [['create-student','create','student-error'],['reset-student','reset','reset-error']])if($('#'+id))$('#'+id).onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await request('/functions/v1/manage-student',{method:'POST',body:{action,...Object.fromEntries(new FormData(e.target))}});await load();render();toast(action==='create'?'학생 계정을 발급했습니다.':'비밀번호를 재설정했습니다.')}catch(x){$('#'+out).textContent=x.message}finally{e.submitter.disabled=false}};
 if($('#links')){$('#links').oninput=()=>dirty=true;$('#links').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const f=new FormData(e.target);const rows=Array.from({length:70},(_,i)=>({lecture:i+1,url:f.get('lecture'+(i+1)).trim()}));if(rows.some(r=>r.url&&!validUrl(r.url)))throw Error('강의 주소는 https://로 시작하는 주소를 입력해 주세요.');await request('/rest/v1/lecture_links?on_conflict=lecture',{method:'POST',body:rows,prefer:'resolution=merge-duplicates'});links=rows;dirty=false;toast('강의 링크를 저장했습니다.')}catch(x){$('#link-error').textContent=x.message}finally{e.submitter.disabled=false}}}
 if($('#password'))$('#password').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const f=new FormData(e.target);if(f.get('password')!==f.get('confirm'))throw Error('비밀번호가 서로 다릅니다.');await request('/auth/v1/user',{method:'PUT',body:{password:f.get('password')}});e.target.reset();toast('비밀번호를 변경했습니다.')}catch(x){$('#password-error').textContent=x.message}finally{e.submitter.disabled=false}};
}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
if(navigator.modelContext?.registerTool)navigator.modelContext.registerTool({name:'read_my_math_progress',description:'현재 로그인한 사용자의 저장된 수학 학습 진도와 선택한 학습일의 계획을 조회합니다. 기록을 변경하지 않습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>({content:[{type:'text',text:JSON.stringify(me?{day:selected,plan:plan[selected-1],progress:metric(me.id)}:{error:'로그인이 필요합니다.'})}]})});
if(session&&ready){try{await load();view=me.role==='admin'?'admin':'study';render()}catch(x){remember(null);login();toast(x.message)}}else login();

})();
